/* DESIGN PROTOTYPE ONLY. No network transport, real login, navigation or GPS.
   All order mutations are in-memory examples, never application persistence. */
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=(n,c='')=>`<svg class="ic ${c}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[n]||ICONS.info}</svg>`;
const button=(text,act,style='',extra='')=>`<button type="button" class="btn ${style}" data-act="${act}" ${extra}>${text}</button>`;
const tag=(text,c='',icon='')=>`<span class="tag ${c}">${icon?I(icon):''}${text}</span>`;
const note=(text,c='',icon='info')=>`<div class="note ${c}">${I(icon)}<span>${text}</span></div>`;
const cell=(icon,title,sub,act)=>`<button type="button" class="cell" data-act="${act}"><span class="iconbox">${I(icon)}</span><span class="flex"><strong>${title}</strong>${sub?`<p>${sub}</p>`:''}</span>${I('chevron','end')}</button>`;
const SCREENS=[
['home','01','Your deliveries','Work','One next delivery, clear merchant ownership, and a visible online state. Counts here describe the loaded assigned list, not rider earnings.','GET /rider/profile\nGET /rider/orders/assigned'],
['assigned','02','Assigned order','Work','The merchant already assigned this order. The rider reviews pickup and drop-off; there is no separate Accept job endpoint.','GET /rider/orders/:id\nPOST /rider/orders/:id/arrived-shop'],
['pickup','03','Pickup check','Work','A local bag/order check helps avoid mistakes. Only the pickup action is persisted; the current API has no bag-check fields.','POST /rider/orders/:id/picked-up\nBody: {} or verified coordinates'],
['navigate','04','On the way','Work','Address and hand-off navigation dominate. This route artwork is illustrative, not a live GPS map or a routing response.','GET /rider/orders/:id\nPOST /rider/orders/:id/arrived-customer'],
['doorstep','05','At the customer','Work','Separate physical arrival from completion. The rider must receive the delivery code from the customer.','GET /rider/orders/:id\nCurrent state: RIDER_ARRIVED_AT_CUSTOMER'],
['code','06','Cash & delivery code','Work','Cash and parcel acknowledgements are proposed local UX safeguards. Only otp and supported optional fields go to the delivery endpoint.','POST /rider/orders/:id/delivered\nBody: { otp }'],
['complete','07','Delivery completed','Work','Render this only after the delivery result is confirmed. Cash collected is not merchant cash handover or rider income.','GET /rider/orders/:id\nGET /rider/orders/assigned'],
['prepaid','08','Paid order completion','Work','Never label every non-COD method prepaid. This fixture explicitly has paymentStatus = PAID. Unknown payment needs help.','GET /rider/orders/:id\nPOST /rider/orders/:id/delivered'],
['history','09','Delivery history','More','Completed and exception records from the rider history endpoint. Its inspected response is capped at 50. Not an all-time income dashboard.','GET /rider/orders/history'],
['help','10','Help','More','Call hand-off, order issue reporting and platform support remain different actions. No in-app chat or emergency dispatch is invented.','POST /rider/orders/:id/report-issue\nGET /support/tickets'],
['report','11','Report a delivery issue','More','The selected issue is prefixed to a description. Report success only after a saved ticket; reporting does not cancel or complete delivery.','POST /rider/orders/:id/report-issue\nBody: { description }'],
['profile','12','Rider profile','More','Merchant association, read-only account details and device appearance. No unsupported rider-profile editing or shop switching.','GET /rider/profile'],
['appearance','13','Light / Dark / System','More','Theme controls are device preferences, not rider API writes. Preserve screen, input and order state through switching.','Local validated preference only'],
['permissions','14','Location & alerts','More','Explain permission use before OS prompts. Denial does not hide addresses. Location availability is separate from rider Online.','OS permissions\nPOST /rider/location'],
['login','15','Sign in','Access','Phone verification and Google sign-in use existing auth. No inherited merchant password or CNIC fields.','POST /auth/send-otp\nPOST /auth/google-login'],
['login-code','16','Verify phone','Access','Login OTP is not the customer delivery code. Context is rider. Cooldown and code validation must follow the current service.','POST /auth/verify-otp\nBody: { phoneNumber, code, context: "rider" }'],
['shops','17','Find your shop','Access','Only new/unlinked accounts see this. Search approved participating shops; not a platform-wide marketplace of delivery jobs.','GET /rider/shops?q=...'],
['apply','18','Join shop','Access','Shop selection plus profile details. A rider application needs that merchant’s approval; it is not merchant onboarding.','POST /rider/apply\n{ merchantId, fullName, phoneNumber, vehicleType?, vehicleNumber? }'],
['pending','19','Awaiting shop approval','Access','Show pending and inactive accurately. Do not offer a fake auto-approval button. Existing riders skip application.','GET /rider/profile'],
['empty','20','No assignments','States','A successfully loaded empty list is not an API failure. Going online is presence, not a promise of automatic matching.','GET /rider/orders/assigned'],
['offline','21','Connection lost','States','Show cached data as stale. Stop claiming writes succeeded. Navigation/call hand-offs are not server delivery updates.','No successful mutation implied\nRefetch on reconnect'],
['loading','22','Loading','States','Stable skeletons, never false zero metrics. Reduced motion disables shimmer.','Authenticated read pending'],
['error','23','API unavailable','States','No data, not no deliveries. Retry preserves context and does not load demo data in a production implementation.','Failed authenticated read'],
['expired','24','Session expired','States','Hide private order/customer details. Resume the intended task only after reauthentication and a fresh fetch.','Existing refresh / sign-in contract'],
['inactive','25','Account inactive','States','Do not conflate active=false with offline. No self-activation route is invented; explain the shop’s role.','GET /rider/profile'],
['unknown','26','Completion not confirmed','States','Timeout may follow a saved write. Refetch delivery state before retry. Do not automatically resend the completion request.','GET /rider/orders/:id before retry']
];
const params=new URLSearchParams(location.search);
let mode=params.get('theme')||'system';try{mode=params.get('theme')||localStorage.getItem('sb.rider.design.theme')||'system'}catch{}
if(!['light','dark','system'].includes(mode))mode='system';
const sys=matchMedia('(prefers-color-scheme: dark)');
let state={screen:'home',status:'RIDER_ASSIGNED',online:true,payment:'COD',network:true,bag:false,cash:false,handed:false,shop:'rehman',issue:'Customer unavailable',busy:false,permissions:false,alerts:false,toastTimer:null,historyFilter:'All',sheet:null};
const drafts={phone:'',loginCode:'',deliveryCode:'',fullName:'',appPhone:'',vehicle:'MOTORBIKE',vehicleNumber:'',searchShop:'',description:'',note:''};
const infoById=Object.fromEntries(SCREENS.map(x=>[x[0],x]));
const pk=v=>'Rs '+(v/100).toLocaleString('en-PK',{minimumFractionDigits:0,maximumFractionDigits:2});
const statusLabel=s=>({RIDER_ASSIGNED:'Assigned to you',RIDER_ARRIVED_AT_SHOP:'At the shop',ON_THE_WAY:'On the way',RIDER_ARRIVED_AT_CUSTOMER:'At the customer',DELIVERED:'Delivered'}[s]||s);
function theme(){document.documentElement.dataset.theme=mode==='system'?(sys.matches?'dark':'light'):mode;$('#studio-theme').innerHTML=['light','dark','system'].map((x,i)=>`<button data-theme-set="${x}" class="${mode===x?'active':''}" aria-pressed="${mode===x}">${I(['sun','moon','system'][i])}${x[0].toUpperCase()+x.slice(1)}</button>`).join('');document.querySelectorAll('[data-theme-choice]').forEach(el=>{el.classList.toggle('active',el.dataset.themeChoice===mode);el.setAttribute('aria-pressed',String(el.dataset.themeChoice===mode))});try{localStorage.setItem('sb.rider.design.theme',mode)}catch{}}
sys.addEventListener?.('change',()=>{if(mode==='system')theme()});
function scenes(){let group='';$('#screen-list').innerHTML=SCREENS.map(x=>{let head='';if(group!==x[3]){group=x[3];head=`<div class="section-label">${group}</div>`}return head+`<button data-scene="${x[0]}" class="${state.screen===x[0]?'active':''}"><span>${x[1]}</span>${x[2]}</button>`}).join('');$('#mobile-screen').innerHTML=SCREENS.map(x=>`<option value="${x[0]}" ${state.screen===x[0]?'selected':''}>${x[1]} · ${x[2]}</option>`).join('')}
function scene(id){state.network=id!=='offline';state.payment=id==='prepaid'?'PAID':'COD';const states={home:'RIDER_ASSIGNED',assigned:'RIDER_ASSIGNED',pickup:'RIDER_ARRIVED_AT_SHOP',navigate:'ON_THE_WAY',doorstep:'RIDER_ARRIVED_AT_CUSTOMER',code:'RIDER_ARRIVED_AT_CUSTOMER',complete:'DELIVERED',prepaid:'RIDER_ARRIVED_AT_CUSTOMER',offline:'ON_THE_WAY',unknown:'RIDER_ARRIVED_AT_CUSTOMER'};if(states[id])state.status=states[id];state.cash=false;state.handed=false;state.bag=false;drafts.deliveryCode='';go(id)}
function go(id){if(!infoById[id])return;state.screen=id;state.sheet=null;$('#overlay').innerHTML='';render();$('#content').scrollTop=0;}
function map(stage='shop'){return `<div class="map ${stage==='customer'?'standalone':''}" role="img" aria-label="Illustrative location map, not live GPS"><svg class="mapdrawing" viewBox="0 0 350 230" preserveAspectRatio="xMidYMid slice"><rect width="350" height="230" fill="var(--map)"/><g fill="var(--map-block)"><rect x="20" y="17" width="60" height="65" rx="10"/><rect x="103" y="9" width="70" height="48" rx="10"/><rect x="214" y="19" width="95" height="61" rx="12"/><rect x="23" y="114" width="70" height="71" rx="10"/><rect x="132" y="127" width="37" height="88" rx="10"/><rect x="231" y="121" width="92" height="68" rx="12"/></g><g fill="none" stroke="var(--map-road)" stroke-width="13"><path d="M-20 99 370 99M192-10v260M104-10v95L115 250M-10 211h380"/><path d="M320-10v280" stroke-width="7"/></g><path d="M76 148v-49h116v77h68" stroke="var(--surface)" fill="none" stroke-width="12" stroke-linecap="round"/><path d="M76 148v-49h116v77h68" stroke="var(--action)" fill="none" stroke-width="6" stroke-linecap="round"/><circle cx="76" cy="148" r="11" fill="var(--surface)" stroke="var(--action)" stroke-width="3"/><circle cx="76" cy="148" r="4" fill="var(--action)"/><rect x="246" y="162" height="30" width="30" rx="10" fill="var(--action)"/><path d="m254 178 7-6 7 6v8h-14z" fill="none" stroke="white" stroke-width="2"/><text x="25" y="203" fill="var(--quiet)" font-size="9" font-family="Arial">MODEL TOWN · SAMPLE</text></svg><div class="map-caption">${I('pin')}<div><strong>${stage==='customer'?'Customer drop-off':'Pickup at your shop'}</strong><p>Open navigation for directions</p></div></div><span class="map-label">Illustrative map · not live GPS</span></div>`}
function appbar(title='',back='home'){return title?`<button class="iconbtn plain" data-act="go:${back}" aria-label="Back">${I('back')}</button><h3>${title}</h3><button class="iconbtn plain" data-act="go:help" aria-label="Get help">${I('help')}</button>`:`<div class="brandrow"><div class="brand">${LOGO}</div><span class="rider-word">RIDER</span></div><button class="iconbtn" data-act="notifications" aria-label="Notifications">${I('bell')}</button>`}
function nav(active='home'){return `<nav class="bottomnav" aria-label="Primary">${[['home','box','Deliveries'],['history','history','History'],['help','help','Help'],['profile','user','Profile']].map(([id,ic,lab])=>`<button data-act="go:${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="navico">${I(ic)}</span>${lab}</button>`).join('')}</nav>`}
function action(text,act,sub='',disabled=false){return `<div class="actionbar">${button(text,act,'',disabled?'disabled':'')}${sub?`<p>${sub}</p>`:''}</div>`}
function payment(){return state.payment==='PAID'?`<div class="payment paid"><div class="row"><span class="iconbox">${I('shield')}</span><div><strong>Payment confirmed</strong><p class="gap4">Do not collect cash for this order.</p></div></div></div>`:`<div class="payment"><div class="row spread"><div><p>Cash to collect at delivery</p><div class="amount gap4 money">${pk(248000)}</div></div>${I('cash')}</div><p class="gap8">Customer payment · not your earnings</p></div>`}
function steps(current){return `<div class="progress" aria-label="Delivery progress: ${['Pickup','On the way','At customer','Completed'][current-1]}">${[1,2,3,4].map(n=>`<i class="${n<=current?'on':''}"></i>`).join('')}</div>`}
function orderItems(){return `<div class="sectionhead"><h3>Order contents</h3><span class="small muted">5 items</span></div><div class="detail-list"><div class="detail-row"><span class="qty">2 ×</span><span class="flex">Milk · 1 litre</span></div><div class="detail-row"><span class="qty">1 ×</span><span class="flex">Bread · large loaf</span></div><div class="detail-row"><span class="qty">2 ×</span><span class="flex">Rice · 1 kg</span></div></div>`}
function home(){let done=state.status==='DELIVERED';return `<section><div class="row spread"><div><p class="small muted">Rehman General Store</p><h1 class="gap4">Your deliveries</h1></div><span class="avatar" style="width:45px;height:45px;border-radius:15px;font-size:15px">HA</span></div><div class="availability"><div><span class="strong" style="font-size:13px"><span class="dot"></span>${state.online?'You’re online':'You’re offline'}</span><p class="small muted gap4">${state.online?'Your shop can see your online status.':'Your existing delivery stays assigned.'}</p></div><div class="switch-hit"><button class="switch" role="switch" aria-checked="${state.online}" aria-label="Rider online status" data-act="toggle-online"></button></div></div>${done?`<div class="card"><div class="row"><span class="iconbox">${I('check')}</span><div><h3>Delivery complete</h3><p class="small muted">SB-1048 · Confirmed in this preview</p></div></div>${button('View delivery','go:complete','quietbtn','style="margin-top:16px"')}</div>`:`<div class="hero"><div class="row spread"><span class="label">${state.status==='RIDER_ASSIGNED'?'PICKUP NEXT':'CURRENT DELIVERY'}</span>${tag('SB-1048')}</div><h2 class="gap12">${state.status==='RIDER_ASSIGNED'?'Pick up your order.':'Finish your delivery.'}</h2><div class="trip"><div class="stop"><i></i><div><strong>Rehman General Store</strong><p>Shop 12, Model Town Market</p></div></div><div class="stop"><i></i><div><strong>Ayesha · Model Town</strong><p>Block C · Full address in order</p></div></div></div><div class="divider"></div><div class="row spread small"><span>${I('box')} <span style="vertical-align:super">5 items</span></span><span class="strong">${state.payment==='PAID'?'Payment confirmed':'Collect '+pk(248000)}</span></div>${button(`View delivery ${I('arrow')}`,'open-current','','style="margin-top:14px"')}</div>`}<div class="stats"><div class="stat"><div class="row spread"><strong>${done?1:2}</strong>${I('box')}</div><p>Assigned deliveries</p></div><div class="stat"><div class="row spread"><strong>1</strong>${I('shop')}</div><p>Your delivery shop</p></div></div><div class="sectionhead"><h3>Also assigned</h3><span class="small muted">From your shop</span></div><button class="compact-order" data-act="second-order"><span class="iconbox">${I('box')}</span><span class="flex"><strong>SB-1052</strong><p>Pickup · Block D, Model Town</p></span>${I('chevron')}</button><p class="safe-note">Stop safely before using delivery controls.</p></section>`}
function assigned(){return `<section>${steps(1)}<div class="row spread"><span class="label muted">ORDER SB-1048</span>${tag('Assigned to you','blue')}</div><h1 class="gap12">First, collect<br>from your shop.</h1><p class="muted gap8">Match the order number before pickup.</p><div class="topgap">${map()}</div><div class="card"><div class="row"><span class="iconbox">${I('shop')}</span><div class="flex"><h3>Rehman General Store</h3><p class="small muted gap4">Shop 12, Model Town Market, Lahore</p></div></div><div class="contact-actions">${button(I('route')+' Navigate','navigation','quietbtn')}${button(I('phone')+' Call shop','call-shop','secondary')}</div></div><div class="sectionhead"><h3>Then deliver to</h3></div><div class="row"><span class="iconbox">${I('pin')}</span><div><h3>Ayesha</h3><p class="small muted">Block C, Model Town · Lahore</p></div></div>${payment()}${orderItems()}<button class="link" data-act="pickup-direct">Already at the shop? Confirm pickup ${I('arrow')}</button></section>`}
function pickup(){return `<section>${steps(1)}<div class="row spread"><span class="label muted">ORDER SB-1048</span>${tag('At the shop')}</div><h1 class="gap12">Check it.<br>Then take it.</h1><p class="muted gap8">Confirm the packed order with the shop.</p><div class="card topgap"><div class="row"><span class="iconbox">${I('shop')}</span><div><h3>Rehman General Store</h3><p class="small muted gap4">Pickup order · SB-1048</p></div></div>${orderItems()}</div><div class="gap12">${note('Check sealed bags with shop staff. Do not open sealed goods.','','box')}</div><label class="checkrow gap12"><input type="checkbox" data-flag="bag" ${state.bag?'checked':''}><span>I checked the order number and collected the packed items.</span></label><div class="sectionhead"><h3>Next stop</h3></div><div class="row"><span class="iconbox">${I('pin')}</span><div><strong>Ayesha · Block C</strong><p class="small muted gap4">House 24, Street 6, Model Town</p></div></div>${payment()}</section>`}
function navigate(){return `<section>${steps(2)}<div class="row spread"><span class="label muted">ORDER SB-1048</span>${tag('On the way','blue')}</div><h1 class="gap12">Next stop,<br>Ayesha’s door.</h1><div class="topgap">${map('customer')}</div><div class="card"><p class="label muted">DROP-OFF ADDRESS</p><h3 class="gap8">House 24, Street 6</h3><p class="muted gap4">Block C, Model Town, Lahore</p><div class="note gap12">${I('message')}<span>“Ring the bell at the green gate.”</span></div><div class="contact-actions">${button(I('route')+' Navigate','navigation','quietbtn')}${button(I('phone')+' Call customer','call-customer','secondary')}</div></div>${payment()}<div class="gap12">${note('Location preview only. The native app must show actual tracking permission and connection status.','','location')}</div></section>`}
function doorstep(){return `<section>${steps(3)}<div class="row spread"><span class="label muted">ORDER SB-1048</span>${tag('At the customer')}</div><h1 class="gap12">You’re at<br>the right place.</h1><p class="muted gap8">Hand over the order and ask for the customer’s delivery code.</p><div class="card topgap"><div class="row"><span class="avatar" style="width:44px;height:44px;border-radius:14px;font-size:16px">A</span><div class="flex"><h3>Ayesha</h3><p class="small muted gap4">House 24, Street 6, Block C</p></div><button class="iconbtn" data-act="call-customer" aria-label="Call customer">${I('phone')}</button></div><p class="small muted gap12">Model Town, Lahore</p></div>${payment()}<div class="card topgap"><h3>Before you finish</h3><div class="detail-row"><span class="iconbox" style="width:34px;height:34px;border-radius:10px">${I('box')}</span><p>Hand the packed order to the customer.</p></div><div class="detail-row" style="border:0"><span class="iconbox" style="width:34px;height:34px;border-radius:10px">${I('lock')}</span><p>Ask for their delivery code, not their sign-in code.</p></div></div><button class="link" data-act="go:report">Customer unavailable? Get help ${I('arrow')}</button></section>`}
function code(){const paid=state.payment==='PAID';return `<section>${steps(3)}<div class="row spread"><span class="label muted">ORDER SB-1048</span>${tag(paid?'Payment confirmed':'Cash on delivery',paid?'':'amber')}</div><h1 class="gap12">One last check.</h1><p class="muted gap8">Confirm the handover with the customer.</p>${payment()}<div class="field topgap"><span>Customer’s delivery code</span><input class="input code" id="delivery-code" data-draft="deliveryCode" value="${esc(drafts.deliveryCode)}" inputmode="numeric" autocomplete="off" maxlength="4" placeholder="— — — —" aria-describedby="delivery-code-help"><p id="delivery-code-help" class="small muted">Ask for the 4-digit code shown on the customer’s order. This is not their sign-in code.</p></div><label class="checkrow topgap"><input type="checkbox" data-flag="handed" ${state.handed?'checked':''}><span>I handed the order to the customer.</span></label>${paid?'':`<label class="checkrow gap12"><input type="checkbox" data-flag="cash" ${state.cash?'checked':''}><span>I collected <strong>${pk(248000)}</strong> in cash.</span></label>`}<div id="delivery-error" class="error" role="alert"></div><div class="gap12">${note('Can’t verify the code? Contact the shop. Don’t mark the order delivered.','','shield')}</div><button class="link" data-act="go:report">Get delivery help ${I('arrow')}</button><p class="safe-note">Design review: any four digits demonstrate validation.<br>No production code or verification is used.</p></section>`}
function complete(){return `<section class="center"><div class="success-ring">${I('check')}</div><span class="tag">Delivery completed</span><h1 class="topgap">All handed over.</h1><p class="muted gap8">SB-1048 · Ayesha</p><div class="receipt"><div class="row spread"><span class="label muted">DELIVERY SUMMARY</span>${I('file')}</div><div class="divider"></div><div class="receipt-row"><span>Prepared by</span><strong>Rehman General Store</strong></div><div class="receipt-row"><span>Payment</span><strong>${state.payment==='PAID'?'Paid online':'Cash collected'}</strong></div><div class="receipt-row"><span>Order amount</span><strong class="money">${pk(248000)}</strong></div><div class="receipt-row"><span>Status</span><strong>Delivered</strong></div></div>${note(state.payment==='PAID'?'No cash to collect. Your delivery status is complete.':'Cash belongs to your shop. Follow its handover process; this screen is not a cash receipt from the merchant.','green','shield')}<p class="small muted topgap">Your merchant can see the updated delivery status after backend confirmation.</p><p class="safe-note">Local design state only · no live order changed</p></section>`}
const hist=[['SB-1037','DELIVERED','Today · 9:12 am','COD',187000],['SB-1031','DELIVERED','Yesterday · 6:30 pm','PAID',342500],['SB-1024','FAILED_DELIVERY','Yesterday · 3:05 pm','COD',129000],['SB-1019','DELIVERED','Yesterday · 12:42 pm','COD',94000]];
function history(){return `<section><span class="label muted">YOUR RECENT WORK</span><h1 class="gap8">Delivery history</h1><p class="muted gap8">Review orders assigned to you.</p><div class="segmented">${['All','Delivered','Exceptions'].map(x=>`<button data-filter="${x}" class="${state.historyFilter===x?'active':''}">${x}</button>`).join('')}</div><p class="small muted">Recent records · up to 50 returned by the API</p><div class="gap8">${hist.filter(r=>state.historyFilter==='All'||(state.historyFilter==='Delivered'?r[1]==='DELIVERED':r[1]!=='DELIVERED')).map((r)=>`<button class="history-row" data-act="history-detail:${r[0]}"><span class="iconbox" ${r[1]!=='DELIVERED'?'style="color:var(--amber);background:var(--amber-bg)"':''}>${I(r[1]==='DELIVERED'?'check':'warning')}</span><span class="flex"><strong>${r[0]}</strong><p>${r[2]}</p><p>${r[1]==='DELIVERED'?'Delivered':'Failed delivery'}</p></span><span class="total">${pk(r[4])}<p>Order value</p></span>${I('chevron')}</button>`).join('')}</div><div class="topgap">${note('Order values are customer payments. This is not a rider earnings or cash-balance report.','','cash')}</div></section>`}
function help(){return `<section><span class="label muted">YOU’RE NOT ON YOUR OWN</span><h1 class="gap8">How can we help?</h1><p class="muted gap8">For pickup or delivery changes, start with your shop.</p><div class="card topgap"><div class="row"><span class="iconbox">${I('shop')}</span><div><h3>Rehman General Store</h3><p class="small muted">Your delivery team</p></div></div>${button(I('phone')+' Call your shop','call-shop','quietbtn','style="margin-top:16px"')}</div><div class="sectionhead"><h3>Current delivery</h3></div>${cell('warning','Report a delivery issue','SB-1048 · Describe what happened','go:report')}<div class="sectionhead"><h3>App and account</h3></div>${cell('message','Contact support','Create a ticket for app or account help','support')}${cell('file','Your support requests','View requests and replies','tickets')}${cell('location','Location & alerts','Review device permissions','go:permissions')}<div class="topgap">${note('In immediate danger, contact local emergency services. This support tool is not an emergency service.','amber','shield')}</div></section>`}
function report(){return `<section><span class="label muted">ORDER SB-1048</span><h1 class="gap8">Tell us<br>what happened.</h1><p class="muted gap8">Your shop and support receive the issue. The delivery stays in its current state.</p><div class="field"><span>Issue type</span><select class="input" id="issue-type">${['Customer unavailable','Address unclear','Problem with order','Vehicle problem','Payment or code issue','Other'].map(x=>`<option ${state.issue===x?'selected':''}>${x}</option>`).join('')}</select></div><label class="field"><span>What should the shop know?</span><textarea class="input" data-draft="description" placeholder="Describe what happened and where you are.">${esc(drafts.description)}</textarea></label><p class="small muted gap8">Do not include passwords or delivery codes.</p><div id="report-error" class="error" role="alert"></div><div class="topgap">${note('Do not leave the order or change its delivery status until you have clear instructions.','','info')}</div><button class="link" data-act="call-shop">${I('phone')} Call the shop instead</button></section>`}
function profile(){return `<section><div class="row"><span class="avatar">HA</span><div class="flex"><h1 style="font-size:24px">Hammad Ali</h1><p class="small muted gap4">+92 300 ••• ••14</p></div>${tag('Active')}</div><div class="card topgap"><p class="label muted">YOUR SHOP</p><div class="row gap12"><span class="iconbox">${I('shop')}</span><div><h3>Rehman General Store</h3><p class="small muted gap4">Model Town, Lahore</p></div></div><div class="divider"></div><div class="row spread"><span class="small muted">Vehicle</span><strong class="small">Motorbike</strong></div><div class="row spread gap12"><span class="small muted">Account approval</span>${tag('Approved')}</div></div><div class="sectionhead"><h3>Preferences</h3></div>${cell('sun','Appearance','Light, Dark or follow your device','go:appearance')}${cell('location','Location & alerts','Device permissions and tracking','go:permissions')}${cell('help','Help & support','Contact your shop or support','go:help')}<div class="gap12">${note('Your shop manages rider details. Contact the owner for changes.','','lock')}</div><button class="link dangertext topgap" data-act="logout">${I('logout')} Sign out</button><div class="slogan">${SLOGAN}</div></section>`}
function appearance(){return `<section><span class="label muted">MAKE IT COMFORTABLE</span><h1 class="gap8">Your app.<br>Your light.</h1><p class="muted gap8">Choose an appearance that suits you. System follows your device.</p><div class="appearance">${['light','dark','system'].map(x=>`<button data-theme-choice="${x}" data-theme-set="${x}" class="${mode===x?'active':''}" aria-pressed="${mode===x}"><span class="mode-preview ${x}"><i></i><i></i></span>${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="sectionhead"><h3>Preview</h3></div><div class="card"><div class="row"><span class="iconbox">${I('box')}</span><div class="flex"><h3>Ready for pickup</h3><p class="small muted gap4">Rehman General Store</p></div>${tag('Assigned','blue')}</div>${button('View delivery '+I('arrow'),'go:assigned','','style="margin-top:20px"')}</div><div class="topgap">${note('Changing appearance won’t change your delivery, entered code or online status.','','shield')}</div><div class="card topgap"><div class="row"><span class="iconbox">${I('system')}</span><div><h3>Reduced motion</h3><p class="small muted gap4">Follows your device preference</p></div></div><p class="small muted gap12">Core actions remain clear without decorative movement.</p></div></section>`}
function permissions(){return `<section><span class="label muted">DEVICE ACCESS</span><h1 class="gap8">Stay connected<br>to your delivery.</h1><p class="muted gap8">Review what the app uses and when.</p><div class="card topgap"><div class="row spread"><span class="iconbox">${I('location')}</span>${tag(state.permissions?'Preview enabled':'Not enabled',state.permissions?'':'amber')}</div><h3 class="gap12">Location during delivery</h3><p class="small muted gap8">Show your progress to your shop and customer during an active delivery.</p>${button('Review location access','location-permission','quietbtn','style="margin-top:14px"')}</div><div class="card gap12"><div class="row"><span class="iconbox">${I('bell')}</span><div><h3>Delivery alerts</h3><p class="small muted gap4">New assignments and important updates</p></div></div>${button('Review notification access','notification-permission','secondary','style="margin-top:14px"')}</div><div class="topgap">${note('Online status and GPS access are different. Without location, addresses remain readable; location updates may be unavailable.','','info')}</div><p class="small muted topgap">Opening another navigation app can interrupt foreground-only tracking. Background access requires native setup and device testing.</p></section>`}
function login(){return `<section><div class="auth-art"><span class="orb"></span><span class="bigicon">${I('box')}</span><span class="art-tag">${I('check')} Your shop. Your deliveries.</span></div><span class="label muted">SIRFBAZAR RIDER</span><h1 class="gap8">Let’s get you<br>on the road.</h1><p class="muted gap8">Sign in with the number your shop knows.</p><label class="field"><span>Mobile number</span><span class="phonefield"><span class="prefix">+92</span><input class="input" data-draft="phone" value="${esc(drafts.phone)}" inputmode="tel" autocomplete="tel-national" maxlength="10" placeholder="3XX XXXXXXX"></span></label><div id="login-error" class="error" role="alert"></div>${button('Send sign-in code '+I('arrow'),'send-login','','style="margin-top:18px"')}<div class="or">or</div>${button('Continue with Google','google','secondary')}<p class="small muted center topgap">New rider? Sign in first, then request to join your shop.</p><div class="slogan">${SLOGAN}</div></section>`}
function loginCode(){return `<section><div class="center"><span class="iconbox">${I('lock')}</span></div><span class="label muted">VERIFY YOUR PHONE</span><h1 class="gap8">Check your<br>messages.</h1><p class="muted gap12">Enter the sign-in code sent to<br><strong>+92 ${drafts.phone?esc(drafts.phone.slice(0,3))+' ••• ••'+esc(drafts.phone.slice(-2)):'3XX ••• ••XX'}</strong></p><button class="link" data-act="go:login">Change number</button><label class="field"><span>Sign-in code</span><input class="input code" data-draft="loginCode" value="${esc(drafts.loginCode)}" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="• • • • • •"></label><div id="otp-error" class="error" role="alert"></div><button class="link gap12" data-act="resend">Resend code</button><div class="topgap">${note('This signs you in. A customer’s delivery code is requested later, at drop-off.','','shield')}</div><p class="safe-note">Prototype only: any 4–6 digits continue the example.<br>No SMS is sent.</p></section>`}
function shops(){let q=drafts.searchShop.toLowerCase();let list=[['rehman','Rehman General Store','Model Town · Lahore'],['daily','Daily Essentials','Garden Town · Lahore']];return `<section><div class="steps"><b>1</b> Your shop <i></i><span>2 · Your details</span></div><h1>Deliver for<br>a shop you know.</h1><p class="muted gap8">Find your shop and ask its owner to add you to the delivery team.</p><label class="field"><span>Find your shop</span><input class="input" data-draft="searchShop" value="${esc(drafts.searchShop)}" placeholder="Search by shop name" autocomplete="off"></label><p class="small muted topgap">Participating shops</p><div id="shop-results">${list.filter(x=>x[1].toLowerCase().includes(q)).map(([id,name,loc])=>`<button class="choice ${state.shop===id?'selected':''}" data-shop="${id}"><span class="iconbox">${I('shop')}</span><span><h3>${name}</h3><p>${loc}</p></span><span class="radio"></span></button>`).join('')||`<p class="muted topgap">No matching shop in this sample list.</p>`}</div><div class="topgap">${note('Already added by a shop? Recheck your account before applying again.','','info')}</div><button class="link" data-act="account-check">Recheck my account</button></section>`}
function apply(){return `<section><div class="steps"><span>1 · Your shop</span><i></i><b>2</b> Your details</div><h1>Meet your<br>new delivery team.</h1><p class="muted gap8">Request to join ${state.shop==='rehman'?'Rehman General Store':'Daily Essentials'}.</p><label class="field"><span>Full name</span><input class="input" data-draft="fullName" value="${esc(drafts.fullName)}" placeholder="Your full name" autocomplete="name"></label><label class="field"><span>Contact number</span><input class="input" data-draft="appPhone" value="${esc(drafts.appPhone)}" placeholder="+92 3XX XXXXXXX" inputmode="tel"></label><label class="field"><span>Vehicle type <span class="muted">· optional</span></span><select class="input" data-draft="vehicle">${[['MOTORBIKE','Motorbike'],['BICYCLE','Bicycle'],['CAR','Car'],['ON_FOOT','On foot']].map(([val,lab])=>`<option value="${val}" ${drafts.vehicle===val?'selected':''}>${lab}</option>`).join('')}</select></label><label class="field"><span>Vehicle number <span class="muted">· optional</span></span><input class="input" data-draft="vehicleNumber" value="${esc(drafts.vehicleNumber)}" placeholder="Number shown on your vehicle"></label><div id="apply-error" class="error" role="alert"></div><div class="topgap">${note('Your shop reviews this request. You can deliver once your rider account is approved and active.','','shield')}</div></section>`}
function pending(){return `<section class="center"><span class="iconbox" style="background:var(--amber-bg);color:var(--amber)">${I('clock')}</span>${tag('Awaiting shop approval','amber')}<h1 class="topgap">You’re nearly<br>on the team.</h1><p class="muted gap12">Your request was sent to<br><strong>${state.shop==='rehman'?'Rehman General Store':'Daily Essentials'}</strong>.</p><div class="card topgap" style="text-align:left"><div class="detail-row"><span class="iconbox">${I('check')}</span><div><h3>Request submitted</h3><p class="small muted">Your shop has your details.</p></div></div><div class="detail-row" style="border:0"><span class="iconbox" style="background:var(--amber-bg);color:var(--amber)">${I('clock')}</span><div><h3>Shop review</h3><p class="small muted">Waiting for the owner’s decision.</p></div></div></div><div class="topgap">${note('No need to apply again. Check with your shop owner if you need an update.','','info')}</div><button class="link topgap" data-act="pending-refresh">${I('refresh')} Check approval status</button></section>`}
function empty(){return `<section><p class="small muted">Rehman General Store</p><h1 class="gap8">Your deliveries</h1><div class="statuscard">${I('check')}<div><strong>You’re online</strong><p>Your shop can see your status.</p></div></div><div class="empty-art"><span class="iconbox">${I('box')}</span></div><h2 class="center">Nothing assigned yet.</h2><p class="muted center gap12">New deliveries appear here after your shop assigns them to you.</p>${button('Refresh deliveries '+I('refresh'),'refresh-empty','secondary','style="margin-top:22px"')}<div class="card topgap"><div class="row"><span class="iconbox">${I('shop')}</span><div><h3>Your delivery shop</h3><p class="small muted">Rehman General Store</p></div></div><button class="link" data-act="call-shop">Contact your shop ${I('arrow')}</button></div></section>`}
function offline(){return `<section>${note('Connection lost. Showing the last saved delivery view. No update has been sent.','amber','wifi')}<div class="row spread topgap"><span class="label muted">ORDER SB-1048</span>${tag('Last known: on the way','amber')}</div><h1 class="gap12">Your address<br>is still here.</h1><div class="card topgap"><p class="label muted">SAVED DROP-OFF</p><h3 class="gap8">Ayesha · House 24, Street 6</h3><p class="muted gap8">Block C, Model Town, Lahore</p><p class="small muted gap12">“Ring the bell at the green gate.”</p><div class="contact-actions">${button(I('phone')+' Call','call-customer','secondary')}${button(I('route')+' Navigate','navigation','quietbtn')}</div></div>${payment()}<div class="topgap">${note('Do not retry a delivery confirmation until you know its saved status. Reconnect and refresh first.','','info')}</div></section>`}
function render(){scenes();let id=state.screen;let x=infoById[id];$('#note-title').textContent=x[2];$('#note-copy').textContent=x[4];$('#note-api').textContent=x[5];let body='',foot=nav(),title='',back='home';if(id==='home')body=home();else if(id==='assigned'){body=assigned();title='Delivery details';foot=action('I’m at the shop '+I('arrow'),'arrived-shop','Confirm only when you have arrived.')}else if(id==='pickup'){body=pickup();title='Confirm pickup';back='assigned';foot=action('Confirm pickup '+I('arrow'),'confirm-pickup','This moves the order to On the way.',!state.bag)}else if(id==='navigate'){body=navigate();title='Active delivery';foot=action('I’ve arrived '+I('arrow'),'arrived-customer','Stop safely before confirming arrival.')}else if(id==='doorstep'||id==='prepaid'){body=doorstep();title='At drop-off';foot=action('Confirm handover '+I('arrow'),'go:code')}else if(id==='code'){body=code();title='Complete delivery';back='doorstep';foot=action('Verify & complete '+I('check'),'complete-delivery','Wait for confirmation before leaving.',!canComplete())}else if(id==='complete'){body=complete();title='Delivery receipt';foot=action('Back to deliveries '+I('arrow'),'go:home')}else if(id==='history'){body=history();foot=nav('history')}else if(id==='help'){body=help();foot=nav('help')}else if(id==='report'){body=report();title='Delivery help';back='help';foot=action('Send issue to the shop '+I('arrow'),'send-issue','Reporting does not change the order’s status.')}else if(id==='profile'){body=profile();foot=nav('profile')}else if(id==='appearance'){body=appearance();title='Appearance';back='profile';foot=nav('profile')}else if(id==='permissions'){body=permissions();title='Location & alerts';back='profile';foot=nav('profile')}else if(id==='login'){body=login();foot=''}else if(id==='login-code'){body=loginCode();title='Verify phone';back='login';foot=action('Continue '+I('arrow'),'verify-login')}else if(id==='shops'){body=shops();title='Join a delivery team';back='login';foot=action('Continue '+I('arrow'),'go:apply')}else if(id==='apply'){body=apply();title='Your rider details';back='shops';foot=action('Send join request '+I('arrow'),'apply','No account or shop is created in this preview.')}else if(id==='pending'){body=pending();title='Your application';back='login';foot=action('Back to sign in','go:login')}else if(id==='empty'){body=empty();foot=nav()}else if(id==='offline'){body=offline();title='Delivery · offline';foot=action('Reconnect & check status '+I('refresh'),'reconnect')}else if(id==='loading'){body=`<section><h1>Your deliveries</h1><p class="muted gap8" role="status">Checking with your shop…</p><div class="skeleton" style="height:54px"></div><div class="skeleton" style="height:292px"></div><div class="skeleton" style="height:80px"></div></section>`}else if(id==='error'){body=`<section class="center"><span class="iconbox" style="color:var(--red);background:var(--red-bg)">${I('wifi')}</span><h1>Couldn’t load<br>your deliveries.</h1><p class="muted gap12">We couldn’t reach the service. Your assignments haven’t been changed.</p>${button('Try again '+I('refresh'),'retry','', 'style="margin-top:26px"')}<p class="small muted topgap">This is a connection problem, not an empty delivery list.</p></section>`}else if(id==='expired'){body=`<section class="center"><span class="iconbox">${I('lock')}</span><h1>Sign in again<br>to continue.</h1><p class="muted gap12">Your session has ended. We’ve hidden private delivery details until you sign in.</p><div class="topgap">${note('After signing in, refresh the order before taking your next delivery action.','','shield')}</div></section>`;title='Session ended';back='login';foot=action('Sign in '+I('arrow'),'go:login')}else if(id==='inactive'){body=`<section class="center"><span class="iconbox" style="color:var(--amber);background:var(--amber-bg)">${I('shield')}</span>${tag('Account inactive','amber')}<h1 class="topgap">Check in with<br>your shop.</h1><p class="muted gap12">Rehman General Store manages your rider access. Contact the owner to review your account.</p><div class="topgap">${note('This is different from being offline. The Online switch cannot reactivate an account.','','info')}</div></section>`;foot=action('Contact your shop '+I('phone'),'call-shop')}else if(id==='unknown'){body=`<section class="center"><span class="iconbox" style="color:var(--amber);background:var(--amber-bg)">${I('refresh')}</span>${tag('Confirmation pending','amber')}<h1 class="topgap">Let’s check<br>before retrying.</h1><p class="muted gap12">The connection dropped after your request. The order may already be saved as delivered.</p><div class="card topgap" style="text-align:left"><h3>Do not collect payment again.</h3><p class="small muted gap8">Keep the customer informed while we check the saved delivery state.</p></div><button class="link topgap" data-act="call-shop">Call your shop</button></section>`;title='Check delivery status';foot=action('Check saved status '+I('refresh'),'resolve-unknown')}
$('#appbar').innerHTML=appbar(title,back);$('#content').innerHTML=body;$('#footer').innerHTML=foot;theme();}
function canComplete(){return drafts.deliveryCode.length===4&&state.handed&&(state.payment==='PAID'||state.cash)&&!state.busy&&state.network}
function updateButtons(){let p=document.querySelector('[data-act="confirm-pickup"]');if(p)p.disabled=!state.bag;let b=document.querySelector('[data-act="complete-delivery"]');if(b)b.disabled=!canComplete()}
let focusBefore=null;function sheet(title,content){focusBefore=document.activeElement;state.sheet=title;$('#overlay').innerHTML=`<div class="sheetbackdrop"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="handle"></div><div class="sheethead"><h2 id="sheet-title">${title}</h2><button class="iconbtn plain" data-act="close-sheet" aria-label="Close dialog">${I('close')}</button></div>${content}</section></div>`;setTimeout(()=>$('#overlay').querySelector('button,input,textarea')?.focus(),20)}
function closeSheet(){state.sheet=null;$('#overlay').innerHTML='';if(focusBefore?.isConnected)focusBefore.focus()}
function toast(text){clearTimeout(state.toastTimer);$('#toast-host').innerHTML=`<div class="toast">${esc(text)}</div>`;state.toastTimer=setTimeout(()=>$('#toast-host').innerHTML='',3600)}
async function localAction(el,callback){if(state.busy)return;if(!state.network){toast('No connection. The update was not sent.');return}state.busy=true;let old=el?.innerHTML;if(el){el.disabled=true;el.textContent='Confirming…'}await new Promise(r=>setTimeout(r,230));state.busy=false;callback();if(el?.isConnected){el.innerHTML=old;el.disabled=false}}
async function act(a,el){if(a.startsWith('go:')){go(a.slice(3));return}if(a==='close-sheet'){closeSheet();return}if(a==='cycle-theme'){mode={light:'dark',dark:'system',system:'light'}[mode];theme();return}if(a==='reset'){state.status='RIDER_ASSIGNED';state.payment='COD';state.online=true;state.network=true;state.bag=state.cash=state.handed=false;drafts.deliveryCode='';go('home');return}
if(a==='open-current'){go(({RIDER_ASSIGNED:'assigned',RIDER_ARRIVED_AT_SHOP:'pickup',ON_THE_WAY:'navigate',RIDER_ARRIVED_AT_CUSTOMER:'doorstep',DELIVERED:'complete'})[state.status]||'assigned');return}
if(a==='toggle-online'){if(!state.online){state.online=true;render();toast('Preview: online status changed.');return}sheet('Go offline?',`<p class="muted">Your shop will see you as offline. Existing deliveries remain assigned; this does not cancel them.</p>${button('Go offline','confirm-offline')}${button('Keep me online','close-sheet','secondary')}`);return}
if(a==='confirm-offline'){state.online=false;closeSheet();render();return}
if(a==='arrived-shop'){await localAction(el,()=>{state.status='RIDER_ARRIVED_AT_SHOP';go('pickup')});return}
if(a==='pickup-direct'){state.bag=false;go('pickup');return}
if(a==='confirm-pickup'){if(!state.bag)return;sheet('Start this delivery?',`<p class="muted">Confirm you have order <strong>SB-1048</strong>. The saved status changes to On the way.</p><div class="gap12">${note('No stock or payment is changed by this local preview.','','box')}</div>${button('Order picked up '+I('check'),'save-pickup')}${button('Not yet','close-sheet','secondary')}`);return}
if(a==='save-pickup'){await localAction(el,()=>{state.status='ON_THE_WAY';go('navigate')});return}
if(a==='arrived-customer'){await localAction(el,()=>{state.status='RIDER_ARRIVED_AT_CUSTOMER';go('doorstep')});return}
if(a==='complete-delivery'){if(!canComplete())return;await localAction(el,()=>{state.status='DELIVERED';drafts.deliveryCode='';go('complete')});return}
if(a==='send-login'){let p=drafts.phone.replace(/\D/g,'');if(!/^3\d{9}$/.test(p)){$('#login-error').textContent='Enter a 10-digit Pakistan mobile number starting with 3.';return}await localAction(el,()=>go('login-code'));return}
if(a==='verify-login'){if(drafts.loginCode.length<4){$('#otp-error').textContent='Enter the code from your message.';return}sheet('Choose a review path',`<p class="muted">This prototype does not sign you in. In the app, the authenticated response chooses the correct destination.</p>${button('Preview existing rider','go:home')}${button('Preview new rider','go:shops','secondary')}`);return}
if(a==='resend'){toast('Preview only: no SMS sent. Production must enforce the returned cooldown.');return}
if(a==='google'){sheet('Google sign-in',`<p class="muted">Use the existing native Google flow. Cancelled sign-in must keep the current screen.</p><p class="small muted topgap">This reference does not collect Google credentials or create an account.</p>${button('Preview new rider path','go:shops')}${button('Cancel','close-sheet','secondary')}`);return}
if(a==='account-check'){toast('Preview: inspect the actual authenticated rider association before applying.');return}
if(a==='apply'){if(!drafts.fullName.trim()||!/^\+?\d{10,15}$/.test(drafts.appPhone.replace(/\s/g,''))){$('#apply-error').textContent='Enter your full name and a valid contact number.';return}await localAction(el,()=>go('pending'));return}
if(a==='pending-refresh'){toast('Preview: your request is still pending. Only your shop can approve it.');return}
if(a==='navigation'){sheet('Open navigation',`<p class="muted">Directions open in an external maps app using this order’s saved destination.</p><div class="gap12">${note('No external app is opened by this prototype. The route drawing is illustrative, not actual directions.','','route')}</div><p class="small muted topgap">Native implementation: handle missing coordinates, missing maps app and permission failures. Address fallback remains available.</p>${button('Back to delivery','close-sheet')}`);return}
if(a==='call-shop'||a==='call-customer'){sheet(a==='call-shop'?'Call your shop':'Call the customer',`<p class="muted">The native app opens the phone dialer with the authorized contact number. No masked-calling service is implied.</p><div class="gap12">${note('This preview does not dial any number.','','phone')}</div>${button('Back','close-sheet')}`);return}
if(a==='second-order'){sheet('Also assigned · SB-1052',`<p class="muted">This order belongs to the same shop. Your merchant chooses assignments; no route optimization or delivery priority is implied by list order.</p><div class="card topgap"><p class="label muted">PICKUP</p><h3 class="gap8">Rehman General Store</h3><p class="small muted gap4">Drop-off: Block D, Model Town</p></div>${button('Close order','close-sheet')}`);return}
if(a.startsWith('history-detail:')){let r=hist.find(x=>x[0]===a.split(':')[1]);sheet('Delivery '+r[0],`<p class="muted">${r[1]==='DELIVERED'?'Delivered':'Failed delivery'} · ${r[2]}</p><div class="receipt"><div class="receipt-row"><span>Order value</span><strong>${pk(r[4])}</strong></div><div class="receipt-row"><span>Merchant</span><strong>Rehman General Store</strong></div></div><p class="small muted">Order details are fetched with the rider-authorized detail endpoint. Historic actions remain read-only.</p>${button('Close details','close-sheet')}`);return}
if(a==='send-issue'){if(drafts.description.trim().length<8){$('#report-error').textContent='Add a short description so your shop can help.';return}await localAction(el,()=>sheet('Issue reported',`<span class="tag">Local preview</span><h3 class="topgap">Your delivery status is unchanged.</h3><p class="muted gap8">In the app, display the saved ticket only after the backend confirms it.</p><p class="small muted gap12">No support message was sent by this prototype.</p>${button('Back to delivery','open-current')}`));return}
if(a==='support'){sheet('Contact support',`<label class="field"><span>Subject</span><input class="input" id="support-subject" placeholder="What do you need help with?"></label><label class="field"><span>Message</span><textarea class="input" id="support-message" placeholder="Describe the problem."></textarea></label><p class="small muted gap12">App/account support, not an emergency service.</p><div id="support-error" class="error" role="alert"></div>${button('Preview send request','send-support')}`);return}
if(a==='send-support'){if(!$('#support-subject').value.trim()||!$('#support-message').value.trim()){$('#support-error').textContent='Enter a subject and message.';return}closeSheet();toast('Local preview only. A real request would use /support/tickets.');return}
if(a==='tickets'){sheet('Your support requests',`<p class="muted">No requests in this fictional account.</p><div class="topgap">${note('Production: distinguish a successful empty list from a failed request.','','file')}</div>${button('Contact support','support','secondary')}`);return}
if(a==='notifications'){sheet('Notifications',`<div class="row topgap"><span class="iconbox">${I('box')}</span><div><h3>New delivery assigned</h3><p class="small muted gap4">Rehman General Store · SB-1048</p></div></div><p class="small muted topgap">Fictional notification. Opening this sheet does not mark any production message read.</p>${button('Open delivery','open-current')}`);return}
if(a==='location-permission'){sheet('Share delivery progress',`<p class="muted">Your location helps your shop and customer follow an active delivery. You can review access in device settings.</p><p class="small muted topgap">Request foreground access first. Background delivery tracking requires separate native setup and consent. This preview never requests GPS.</p>${button('Preview enabled state','enable-location')}${button('Not now','close-sheet','secondary')}`);return}
if(a==='enable-location'){state.permissions=true;closeSheet();render();return}
if(a==='notification-permission'){sheet('Allow delivery alerts',`<p class="muted">Alerts can tell you when the shop assigns a delivery. Review the native system prompt before deciding.</p><p class="small muted topgap">No system permissions are changed by this prototype.</p>${button('Preview enabled state','enable-alerts')}${button('Not now','close-sheet','secondary')}`);return}
if(a==='enable-alerts'){state.alerts=true;closeSheet();toast('Preview state only: alerts enabled.');return}
if(a==='logout'){sheet('Sign out?',`<p class="muted">Signing out does not cancel assigned work. An active delivery still needs your shop’s attention.</p>${button('Sign out','signout','danger')}${button('Stay signed in','close-sheet','secondary')}`);return}
if(a==='signout'){Object.keys(drafts).forEach(k=>drafts[k]='');go('login');return}
if(a==='refresh-empty'){toast('Preview: no deliveries assigned.');return}
if(a==='retry'){go('home');toast('Local recovery example. Production must wait for a successful read.');return}
if(a==='reconnect'){state.network=true;go('navigate');toast('Local example: last saved state is On the way.');return}
if(a==='resolve-unknown'){sheet('Saved status: at customer',`<p class="muted">This example shows an order that was not completed. In production, use the refreshed server state, never this fixed result.</p>${button('Review handover again','go:code')}`);return}
}
document.addEventListener('click',e=>{let t=e.target.closest('[data-theme-set]');if(t){mode=t.dataset.themeSet;theme();return}let s=e.target.closest('[data-scene]');if(s){scene(s.dataset.scene);return}let sh=e.target.closest('[data-shop]');if(sh){state.shop=sh.dataset.shop;render();return}let f=e.target.closest('[data-filter]');if(f){state.historyFilter=f.dataset.filter;render();return}let a=e.target.closest('[data-act]');if(a&&!a.disabled)act(a.dataset.act,a)});
document.addEventListener('input',e=>{let k=e.target.dataset.draft;if(k){let v=e.target.value;if(['deliveryCode','loginCode','phone'].includes(k)){v=v.replace(/\D/g,'');e.target.value=v}drafts[k]=v;if(k==='searchShop'){let pos=e.target.selectionStart;let scroll=$('#content').scrollTop;render();let inp=$('[data-draft="searchShop"]');inp.focus();inp.setSelectionRange(pos,pos);$('#content').scrollTop=scroll}updateButtons()}});
document.addEventListener('change',e=>{if(e.target.dataset.flag){state[e.target.dataset.flag]=e.target.checked;updateButtons()}if(e.target.id==='mobile-screen')scene(e.target.value);if(e.target.id==='issue-type')state.issue=e.target.value;if(e.target.dataset.draft)drafts[e.target.dataset.draft]=e.target.value});
document.addEventListener('keydown',e=>{if(!state.sheet)return;let sh=$('.sheet');if(e.key==='Escape'){e.preventDefault();closeSheet()}if(e.key==='Tab'&&sh){let a=[...sh.querySelectorAll('button:not(:disabled),input:not(:disabled),textarea,select,a[href]')].filter(x=>x.getClientRects().length);let first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.__riderDesign={scene,go,state,drafts,setTheme:x=>{mode=x;theme()},screens:SCREENS.map(x=>({id:x[0],name:x[2]}))};
if(params.get('capture')==='1')document.body.classList.add('capture');scene(infoById[params.get('screen')]?params.get('screen'):'home');
